-- Oracle EBS R12 -> canonical GOODS_RECEIPT (ORACLE_EBS). Generated by tools/build_silver_sql.py.
SELECT 'ORACLE_EBS' AS SOURCE_SLOT, 'Oracle EBS R12' AS SOURCE_SYSTEM, r.TRANSACTION_ID::STRING AS GR_DOC, h.SEGMENT1 AS PO_NUMBER, l.LINE_NUM::STRING AS PO_ITEM, 'ORACLE_EBS' AS PLANT,
  r.VENDOR_ID::STRING AS SUPPLIER_ID, l.ITEM_NUMBER AS MATERIAL, r.TRANSACTION_DATE AS GR_DATE, r.QUANTITY AS GR_QTY,
  r.QUANTITY * l.UNIT_PRICE AS GR_VALUE, h.CURRENCY_CODE AS CURRENCY
FROM {{ source('src_oracle_ebs', 'rcv_transactions') }} r JOIN {{ source('src_oracle_ebs', 'po_lines_all') }} l ON l.PO_LINE_ID = r.PO_LINE_ID
JOIN {{ source('src_oracle_ebs', 'po_headers_all') }} h ON h.PO_HEADER_ID = l.PO_HEADER_ID WHERE r.TRANSACTION_TYPE = 'RECEIVE'
